const https = require('https');
const crypto = require('crypto');
const cheerio = require('cheerio');

const BASE_URL = "https://temp-mail.app";
const MAX_RETRIES = 20;
const RETRY_DELAY = 3000;

let sessionState = {
    cookie: "",
    visitorId: crypto.randomUUID(),
    currentEmail: null
};

function apiRequest(path, params = {}) {
    const urlObj = new URL(`${BASE_URL}${path}`);
    Object.keys(params).forEach(key => urlObj.searchParams.append(key, params[key]));

    return new Promise((resolve, reject) => {
        const options = {
            hostname: urlObj.hostname,
            path: urlObj.pathname + urlObj.search,
            method: 'GET',
            headers: {
                'Accept': '*/*',
                'User-Agent': 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Mobile Safari/537.36',
                'Cache-Control': 'no-cache',
                'Visitor-Id': sessionState.visitorId, 
                'Cookie': sessionState.cookie
            }
        };

        const req = https.request(options, (res) => {
            let data = '';
            if (res.headers['set-cookie']) {
                sessionState.cookie = res.headers['set-cookie'].join('; ');
            }
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                try { resolve(JSON.parse(data)); } 
                catch (e) { reject(new Error("Invalid JSON")); }
            });
        });
        req.on('error', reject);
        req.end();
    });
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

function parseEmailContent(htmlString) {
    if (!htmlString) return { clean_text: "", links: [] };

    const $ = cheerio.load(htmlString);

    const links = [];
    $('a[href]').each((i, elem) => {
        const href = $(elem).attr('href');
        if (href && (href.startsWith('http://') || href.startsWith('https://'))) {
            links.push(href);
        }
    });

    $('script, style').remove();
    const cleanText = $('body').text().replace(/\n\s*\n/g, '\n').trim();

    return { clean_text: cleanText, links: links };
}

async function getTempMailWithCheerio() {
    const addrRes = await apiRequest('/api/mail/address', {
        refresh: 'true', expire: '1440', part: 'main'
    });

    if (!addrRes.address) throw new Error("Gagal generate email");
    sessionState.currentEmail = addrRes.address;

    console.error(`[INFO] Email: ${sessionState.currentEmail}`);
    console.error(`[INFO] Menunggu email masuk...`);

    for (let i = 1; i <= MAX_RETRIES; i++) {
        await sleep(RETRY_DELAY); 

        const inboxRes = await apiRequest('/api/mail/list', { part: 'main' });
        const messages = inboxRes.message || [];

        if (messages.length > 0) {
            console.error(`[SUCCESS] Ditemukan ${messages.length}`);

            const detailedMessages = messages.map(msg => {
                const parsed = parseEmailContent(msg.content);

                return {
                    id: msg.id,
                    from: msg.fromName || msg.fromAddress,
                    subject: msg.subject,
                    date: msg.date,
                    preview: msg.preview,
                    clean_content: parsed.clean_text,
                    extracted_links: parsed.links
                };
            });

            return {
                status: "success",
                email: sessionState.currentEmail,
                message_count: detailedMessages.length,
                messages: detailedMessages
            };
        } else {
            console.error(`[WAITING] Cek ${i}/${MAX_RETRIES}... Kosong.`);
        }
    }

    throw new Error("Timeout: Email tidak diterima.");
}

